const codes = new Set(languages.map(item => item.code));
const storageKey = 'frame-story-language';

function matchLanguage(value) {
  if (typeof value !== 'string') return null;
  const tag = value.trim().replaceAll('_', '-');
  if (!tag) return null;
  const exact = languages.find(item => item.code.toLowerCase() === tag.toLowerCase());
  if (exact) return exact.code;
  const lower = tag.toLowerCase();
  const primary = lower.split('-')[0];
  if (primary === 'zh') {
    if (lower.includes('-hans')) return 'zh-Hans';
    if (lower.includes('-hant')) return 'zh-Hant';
    if (/(?:^|-)(?:cn|sg)(?:-|$)/.test(lower)) return 'zh-Hans';
    if (/(?:^|-)(?:tw|hk|mo)(?:-|$)/.test(lower)) return 'zh-Hant';
    return 'zh-Hant';
  }
  if (primary === 'tl') return 'fil';
  if (primary === 'nb') return 'no'; // Norwegian Bokmål browser tags.
  return codes.has(primary) ? primary : null;
}

/** Return a supported code, honoring saved manual choice before browser preferences.
 * The UI persists explicit selections with localStorage.setItem('frame-story-language', code).
 * No location, IP lookup or network request is used to select language.
 */
export function selectLanguage(preferred) {
  try {
    const saved = matchLanguage(globalThis.localStorage?.getItem(storageKey));
    if (saved) return saved;
  } catch { /* Private mode/storage restrictions do not prevent language selection. */ }
  let candidates = Array.isArray(preferred) ? preferred : preferred ? [preferred] : [];
  if (!candidates.length) {
    candidates = globalThis.navigator?.languages || [globalThis.navigator?.language];
  }
  for (const candidate of candidates) {
    const selected = matchLanguage(candidate);
    if (selected) return selected;
  }
  return 'en';
}

/** Translate plain text with English fallback and named {variables}.
 * All 256 authored UI keys are explicitly supplied in all 30 locales.
 * Uncatalogued upstream/runtime error messages can still be in English.
 * Callers should render this value as text, not use it as unescaped HTML.
 */
export function t(key, lang, vars = {}) {
  const code = matchLanguage(lang) || (lang == null ? selectLanguage() : 'en');
  const value = messages[code]?.[key] ?? messages.en[key] ?? String(key);
  return value.replace(/\{([A-Za-z0-9_]+)\}/g, (token, name) => {
    const replacement = vars?.[name];
    return replacement == null ? token : String(replacement);
  });
}

/** Machine-readable coverage; does not infer translation quality from string equality.
 * Proper names, standard loanwords, format names and code examples may match English.
 */
export const translationKeys = Object.freeze(Object.keys(messages.en));
export function translationCoverage() {
  return languages.map(({code}) => ({
    code,
    expected: translationKeys.length,
    present: translationKeys.filter(key => typeof messages[code]?.[key] === 'string' && messages[code][key].trim()).length,
    missing: translationKeys.filter(key => typeof messages[code]?.[key] !== 'string' || !messages[code][key].trim())
  }));
}
